const $ = (s,r=document)=>r.querySelector(s);
const el = (tag, cls, html)=>{ const e=document.createElement(tag); if(cls) e.className=cls; if(html!=null) e.innerHTML=html; return e; };
const esc = s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const PLAYABLE_NPCS=Object.entries(NPCS).filter(([id,n],i,all)=>n.look&&all.findIndex(([,other])=>other.name===n.name)===i);
const npcOptions=group=>PLAYABLE_NPCS.filter(([id])=>id.startsWith("valley_")===group).map(([id,n])=>'<option value="'+esc(id)+'">'+esc(n.name)+'</option>').join("");
function drawOpeningScene(ctx,stage,time){const dawn=stage==="dawn",tree=stage==="tree"||dawn,sky=ctx.createLinearGradient(0,0,0,224);sky.addColorStop(0,dawn?"#e7a972":"#273b58");sky.addColorStop(1,dawn?"#f5d7a0":"#8495a0");ctx.fillStyle=sky;ctx.fillRect(0,0,384,224);ctx.fillStyle=dawn?"#ffe1a0":"#536578";for(let i=0;i<5;i++){const x=((i*103-time*4)%470+470)%470-50;ctx.beginPath();ctx.ellipse(x,38+i%2*15,42,11,0,0,Math.PI*2);ctx.ellipse(x+28,35+i%2*15,34,14,0,0,Math.PI*2);ctx.fill();}ctx.fillStyle="#617b88";ctx.fillRect(0,88,384,76);ctx.fillStyle="#769aa0";for(let i=0;i<7;i++){const y=97+i*9;ctx.fillRect((i*71+time*14)%420-30,y,35+(i%3)*12,1);}ctx.fillStyle=dawn?"#ead29d":"#b9aa89";ctx.beginPath();ctx.moveTo(0,145);ctx.quadraticCurveTo(112,126,214,151);ctx.quadraticCurveTo(305,171,384,137);ctx.lineTo(384,224);ctx.lineTo(0,224);ctx.fill();if(tree){ctx.fillStyle="#654936";ctx.beginPath();ctx.moveTo(66,166);ctx.quadraticCurveTo(78,113,96,88);ctx.quadraticCurveTo(108,62,97,39);ctx.quadraticCurveTo(124,72,116,104);ctx.quadraticCurveTo(109,137,123,165);ctx.closePath();ctx.fill();ctx.fillStyle="#304d3c";for(const [x,y,r]of [[82,43,30],[112,39,27],[54,56,24],[132,60,24]]){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}ctx.strokeStyle="#856044";ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(103,153);ctx.lineTo(88,171);ctx.moveTo(108,153);ctx.lineTo(128,169);ctx.stroke();}if(dawn){ctx.fillStyle="#8a6240";ctx.fillRect(254,145,31,21);ctx.fillStyle="#bd9564";ctx.fillRect(254,141,31,7);ctx.fillStyle="#e6c883";ctx.fillRect(267,146,5,5);}if(!dawn){ctx.fillStyle="#252e3b";ctx.beginPath();ctx.arc(182,140,5,0,Math.PI*2);ctx.fill();ctx.fillRect(178,145,8,15);ctx.strokeStyle="#252e3b";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(180,159);ctx.lineTo(176,165);ctx.moveTo(184,159);ctx.lineTo(188,165);ctx.stroke();}if(stage==="storm"){ctx.strokeStyle="#d6e2eb88";for(let i=0;i<52;i++){const x=(i*67+time*86)%400-8,y=(i*43+time*210)%230;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y+8);ctx.stroke();}}}

function drawMapPreview(canvas,n){const M=buildLevel(n),ctx=canvas.getContext("2d"),pal=M.reg.pal,s=Math.min(canvas.width/M.W,canvas.height/M.H),ox=(canvas.width-M.W*s)/2,oy=(canvas.height-M.H*s)/2;ctx.fillStyle="#10131a";ctx.fillRect(0,0,canvas.width,canvas.height);for(let y=0;y<M.H;y++)for(let x=0;x<M.W;x++){const v=M.get(x,y);ctx.fillStyle=v===T.SHALLOW?pal.sh:v===T.DEEP||v===T.LAKE?pal.deep:v===T.VOID?"#111018":v===T.SAND?pal.sand:v===T.SNOW?"#eef4f5":v===T.ICE?"#b9dbe1":v===T.MUD?pal.sand2:v===T.FLOWER?pal.g3:v===T.TALL?pal.g2:v===T.TREE||v===T.BUSH?pal.tree:v===T.ROCK||v===T.CLIFF||v===T.WALL?pal.rock:v===T.HOUSE?pal.trunk:v===T.PATH||v===T.BRIDGE||v===T.PLANK?pal.path:pal.g1;ctx.fillRect(Math.floor(ox+x*s),Math.floor(oy+y*s),Math.ceil(s),Math.ceil(s));}for(const o of M.objs){let color=null,size=1;if(o.kind==="landmark"){color=pal.accent;size=2;}else if(o.kind==="npc"){color="#8fd8ff";}else if(["chest","cache","site","gate"].includes(o.kind)){color="#f4ca70";}if(color){ctx.fillStyle=color;ctx.fillRect(Math.floor(ox+o.tx*s)-size/2,Math.floor(oy+o.ty*s)-size/2,size,size);}}ctx.fillStyle="#fff4d4";ctx.fillRect(Math.floor(ox+M.entry.x*s)-2,Math.floor(oy+M.entry.y*s)-2,4,4);ctx.fillStyle=pal.accent;ctx.fillRect(Math.floor(ox+M.exit.x*s)-2,Math.floor(oy+M.exit.y*s)-2,4,4);}
function blendColor(a,b,t){const h=(x,i)=>parseInt(x.slice(i,i+2),16),v=[1,3,5].map(i=>Math.round(h(a,i)+(h(b,i)-h(a,i))*t).toString(16).padStart(2,"0"));return "#"+v.join("");}
function drawTransitionScene(ctx,from,to,time){const a=REGIONS[Math.floor((from.n-1)/9)],b=REGIONS[Math.floor((to.n-1)/9)],t=Math.max(0,Math.min(1,time/1.4)),mix=(x,y)=>blendColor(x,y,t);const sky=ctx.createLinearGradient(0,0,0,224);sky.addColorStop(0,mix(a.pal.sky1,b.pal.sky1));sky.addColorStop(1,mix(a.pal.sky2,b.pal.sky2));ctx.fillStyle=sky;ctx.fillRect(0,0,384,224);ctx.fillStyle=mix(a.pal.tree,b.pal.tree);ctx.beginPath();ctx.moveTo(0,142);for(let x=0;x<=384;x+=8){const side=x<192?from.n:to.n;ctx.lineTo(x,120+Math.sin(x*.025+side)*12+Math.sin(x*.061+side*2)*5);}ctx.lineTo(384,224);ctx.lineTo(0,224);ctx.fill();ctx.fillStyle=mix(a.pal.g1,b.pal.g1);ctx.beginPath();ctx.moveTo(0,171);ctx.quadraticCurveTo(120,145,196,171);ctx.quadraticCurveTo(285,198,384,158);ctx.lineTo(384,224);ctx.lineTo(0,224);ctx.fill();ctx.strokeStyle=mix(a.pal.path,b.pal.path);ctx.lineWidth=11;ctx.beginPath();ctx.moveTo(0,202);ctx.bezierCurveTo(104,185,260,209,384,177);ctx.stroke();ctx.strokeStyle=mix(a.pal.accent,b.pal.accent);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,202);ctx.bezierCurveTo(104,185,260,209,384,177);ctx.stroke();for(let i=0;i<7;i++){const phase=(time*.5+i/7)%1,x=phase*384,y=202-17*Math.sin(phase*Math.PI)+7*Math.sin(phase*4);ctx.fillStyle=i%2?mix(a.pal.accent,b.pal.accent):"#fff3c8";ctx.globalAlpha=.45+.55*Math.sin(phase*Math.PI);ctx.beginPath();ctx.arc(x,y,1.5+(i%3),0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.fillStyle="#fff3c8aa";ctx.font="8px monospace";ctx.textAlign="center";ctx.fillText(from.land.replace(/_/g," ").toUpperCase(),78,31);ctx.fillText(to.land.replace(/_/g," ").toUpperCase(),306,31);ctx.textAlign="left";}

export const settings = { mode:"2.5d", zoom:1, music:0.5, sfx:0.7, muted:false, textSize:1, typewriter:true, textSpeed:40, reduceMotion:false, reduceFlash:false, touch:"auto", relief:true, hints:true, log:false, highContrast:false };

