export class UI {
  constructor(root){ this.root=root; this.panel=null; this.dlg=null; this.state="title"; this.toasts=$("#toasts"); }
  bind(game){ this.g=game; }
  busy(){ return !!(this.dlg || this.panel || this.levelIntroOpen || this.state!=="play" || this.fading); }

  // ---------------- title ----------------
  showTitle(){ A.setRegion(REGIONS[0]);A.setWeather("mist");this.state="title"; this.closeAll(); $("#hud").hidden=true; $("#touch").hidden=true; const s=$("#screen"); s.className="screen title"; s.hidden=false;
    s.innerHTML = `<canvas id="titleArt" width="384" height="224"></canvas><div class="titleMenu">
      <h1 class="logo big">Where the<br>River Turns</h1>
      <div class="menu" id="tmenu"><button class="btn primary" data-a="new">Begin Journey</button><button class="btn" data-a="meet">Meet the Gurus</button><button class="btn" data-a="continue">Continue Journey</button><button class="btn" data-a="reference">Field Guide</button><button class="btn" data-a="maps">Map Index</button><button class="btn" data-a="sounds">Sound Library</button><button class="btn" data-a="load">Load a save</button><button class="btn" data-a="controls">Controls</button><button class="btn" data-a="settings">Settings</button><button class="btn" data-a="credits">Credits</button></div>
      <p class="small">A quiet adventure along a changing river.</p></div>`;
    this.titleAnim();
    s.querySelectorAll("[data-a]").forEach(b=>b.onclick=()=>{ A.initAudio(); A.sfx("menu"); const a=b.dataset.a; if(a==="new"){if(this.g.run)this.confirm("Start a new journey? Your current progress will be kept as Continue Journey.",()=>{this.storeAutosave();this.showCreate();});else this.showCreate();} if(a==="meet")this.showCreate("meet"); if(a==="continue") this.continueJourney(); if(a==="reference") this.openReference(); if(a==="maps") this.openMapIndex(()=>this.showTitle()); if(a==="sounds") this.openSoundLibrary(); if(a==="load") $("#saveImport").click(); if(a==="controls") this.openControls(); if(a==="settings") this.openSettings(); if(a==="credits") this.showCredits(()=>this.showTitle()); });
    this.focusFirst(s); const file=$("#saveImport"); file.onchange=()=>{ if(file.files[0]) this.loadFile(file.files[0]); file.value=""; }; }
  titleAnim(){ const c=$("#titleArt"); if(!c) return; const x=c.getContext("2d"); let t0=performance.now();this.titleRipples=[];this.titleTsunamiStart=-Infinity;document.getElementById("screen").addEventListener("contextmenu",e=>{e.preventDefault();this.titleTsunamiStart=(performance.now()-t0)/1000;A.sfx("gust");});c.addEventListener("pointerdown",e=>{const r=c.getBoundingClientRect(),px=(e.clientX-r.left)*384/r.width,py=(e.clientY-r.top)*224/r.height;if(py<188)return;this.titleRipples.push({x:px,y:py,t:(performance.now()-t0)/1000});if(this.titleRipples.length>12)this.titleRipples.shift();A.sfx("pickup");});
    const loop=()=>{ if (!document.body.contains(c)) return; const t=(performance.now()-t0)/1000;
      const gr=x.createLinearGradient(0,0,0,224); gr.addColorStop(0,"#2a3450"); gr.addColorStop(1,"#6a7a98"); x.fillStyle=gr; x.fillRect(0,0,384,224);
      const fl = !settings.reduceFlash && Math.sin(t*0.9)*Math.sin(t*2.7)>0.93; if (fl) { x.fillStyle="#ffffff30"; x.fillRect(0,0,384,224); }
      x.fillStyle=fl?"#8a90b0":"#3a4060"; x.beginPath(); x.moveTo(0,150); for(let i=0;i<=384;i+=8) x.lineTo(i, 110+Math.sin(i*0.02)*20+Math.sin(i*0.05)*8 - (i>220&&i<300?30-Math.abs(i-260):0)); x.lineTo(384,224); x.lineTo(0,224); x.fill();
      x.fillStyle="#2a4a3a"; x.beginPath(); x.moveTo(0,170); for(let i=0;i<=384;i+=6) x.lineTo(i,160+Math.sin(i*0.07+1)*6); x.lineTo(384,224); x.lineTo(0,224); x.fill();
      x.fillStyle="#3a6a8a"; x.fillRect(0,190,384,34); for(let i=0;i<20;i++){ x.fillStyle="#8ab0d0"; x.fillRect((i*37+t*14)%384,196+(i%4)*6,10,1); }
      for(let i=0;i<14;i++){ const tx=10+i*28; x.fillStyle="#1a3a2a"; x.fillRect(tx,150-(i%3)*6,14,18); x.fillRect(tx+5,168-(i%3)*6,4,8); }
      const rm=settings.reduceMotion?0.3:1; for(let i=0;i<9;i++){const wx=(i*61+t*(8+i%3*2)*rm)%450-30,wy=196+(i*7)%22+Math.sin(t*1.8+i)*2;x.save();x.translate(wx,wy);x.rotate(Math.sin(t+i)*0.12);x.fillStyle=i%3===0?"#604630":"#443529";x.fillRect(-5,-1,10,2);x.fillStyle="#8c7050";x.fillRect(-3,-2,2,1);if(i%3===1){x.fillStyle="#574735";x.fillRect(1,-3,1,4);x.fillRect(2,-4,3,1);}x.restore();x.fillStyle="#9ac6d0";x.fillRect((wx+4)%384,wy+3,4,1);}this.titleRipples=this.titleRipples.filter(r=>t-r.t<1.2);for(const r of this.titleRipples){const age=Math.max(0,t-r.t),radius=3+age*24,alpha=Math.max(0,1-age/1.2);x.strokeStyle="rgba(210,240,245,"+alpha+")";x.lineWidth=1;x.beginPath();x.ellipse(r.x,r.y,radius,radius*.32,0,0,Math.PI*2);x.stroke();}
      const fishTime=t%19;if(fishTime<2.4&&t>=19){const f=fishTime/2.4,fx=294+Math.sin(f*Math.PI)*26,fy=207-Math.sin(f*Math.PI)*26;x.fillStyle="#75a9bd";x.beginPath();x.ellipse(fx,fy,6,2.5,Math.sin(f*Math.PI)*.4,0,Math.PI*2);x.fill();x.fillStyle="#d5ecdb";x.fillRect(fx+3,fy-1,1,1);x.fillStyle="#a9d7dc";x.beginPath();x.ellipse(fx,207,12+f*9,2,0,0,Math.PI*2);x.stroke();}
      const floodAge=t-this.titleTsunamiStart;if(floodAge>=0&&floodAge<5.8){const progress=Math.max(0,Math.min(1,(floodAge-.35)/3.8)),front=92+progress*158;if(floodAge<.35){x.fillStyle="#91d9e0aa";x.fillRect(245,97,24,3);}else{const g=x.createLinearGradient(0,front-30,0,front+8);g.addColorStop(0,"#8bd9e0c8");g.addColorStop(1,"#3186a8d8");x.fillStyle=g;x.beginPath();for(let px=0;px<=384;px+=4)x.lineTo(px,94+Math.sin(px*.035+floodAge*2)*3);for(let px=384;px>=0;px-=4)x.lineTo(px,front+Math.sin(px*.035+floodAge*5)*4);x.closePath();x.fill();x.strokeStyle="#d1f0e8dd";x.lineWidth=2;x.beginPath();for(let px=0;px<=384;px+=4)x.lineTo(px,front+Math.sin(px*.035+floodAge*5)*4);x.stroke();}if(floodAge>3.8){x.fillStyle="rgba(42,125,161,"+Math.min(.96,(floodAge-3.8)*.8)+")";x.fillRect(0,0,384,224);for(let k=0;k<8;k++){const yy=(k*29+floodAge*26)%224;x.strokeStyle="#c6ebee88";x.beginPath();x.moveTo(0,yy);x.lineTo(384,yy+Math.sin(k+floodAge)*3);x.stroke();}}}
      x.fillStyle="#c8d8f0aa"; for(let i=0;i<70;i++){ x.fillRect((i*53+t*60*rm)%400-8,(i*31+t*260*rm)%230,1,4); }
      requestAnimationFrame(loop); }; loop(); }

  // ---------------- character creation ----------------
  showCreate(startMode="story"){ this.state="create"; const s=$("#screen"); s.className="screen create";
    const cfg = { pres:"boy", mode:startMode, walkBiome:"forest", animal:null, npc:null, npcLook:null, name:"Rowan", pron:"he", hair:"#2a2020", coat:"#5a7a9a", skin:"#e0b090", style:"short" };
    const looks = { boy:{name:"Rowan", pron:"he", hair:"#2a2020", coat:"#5a7a9a", style:"short"}, girl:{name:"Lina", pron:"she", hair:"#2a2020", coat:"#5a8a4a", style:"long"} };
    const animalOptions=ANIMALS.map(a=>'<option value="'+a.id+'">'+esc(a.name)+'</option>').join("");
    const swatch=(k,arr)=>arr.map(c=>`<button class="sw" data-k="${k}" data-v="${c}" style="background:${c}" aria-label="${k} ${c}"></button>`).join("");
    s.innerHTML = `<div class="card wide"><h2>Choose your way through the valley</h2><div class="menu row modeChoices"><button class="btn sel" data-mode="story">Journey · 162 levels</button><button class="btn" data-mode="forest">Explore forest</button><button class="btn" data-mode="garden">Tend garden</button><button class="btn" data-mode="hearth">Quiet rooms</button><button class="btn" data-mode="walk">Take a walk</button><button class="btn" data-mode="nature">Nature</button><button class="btn" data-mode="meet">Meet the guides</button></div>
      <label class="friendlyMode"><input id="friendlyMode" type="checkbox"> Friendly mode <span class="small">Creatures come close with encouragement instead of attacks.</span></label>
      <div id="walkOptions" hidden><label>Choose a walking landscape <select id="walkBiome"><option value="road">Road</option><option value="forest">Forest</option><option value="beach">Beach</option><option value="riverside">Riverside</option><option value="lake">Lake</option><option value="field">Field</option><option value="desert">Desert</option></select></label></div>
      <div class="createGrid"><div><canvas id="heroPrev" width="56" height="72"></canvas></div><div>
      <div class="menu row" id="presRow"><button class="btn" data-p="boy">Boy</button><button class="btn" data-p="girl">Girl</button><button class="btn" data-p="custom">Customize human</button><button class="btn" data-p="animal">Choose an animal</button><button class="btn" data-p="npc">Play as an NPC</button></div>
      <label>Name <input id="hname" maxlength="14" value="Rowan" autocomplete="off"></label>
      <div id="custom" hidden>
        <label>Animal <select id="animal"><option value="">Human</option>${animalOptions}</select></label>
        <p class="small">100 animal sprite choices. Wildlife and foraging descriptions are game content, not field identification advice.</p>
        <label>Pronouns <select id="pron"><option value="he">he / him</option><option value="she">she / her</option><option value="they">they / them</option></select></label>
        <label>Hair style <select id="hstyle"><option value="short">Short</option><option value="long">Shoulder-length</option><option value="tied">Tied back</option></select></label>
        <div class="swrow">Hair ${swatch("hair",["#2a2020","#6a4a2a","#c08a40","#e0d0a0","#8a3a2a","#4a4a6a"])}</div>
        <div class="swrow">Tunic ${swatch("coat",["#5a7a9a","#5a8a4a","#a05a4a","#8a6aa0","#c0a050","#4a8a8a"])}</div>
        <div class="swrow">Skin ${swatch("skin",["#f0c8a0","#e0b090","#c89060","#a06a40","#7a4a2a","#5a3a20"])}</div>
      </div>
      <div id="npcOptions" hidden><label>Choose a character <select id="npcChoice"><optgroup label="Story characters">${npcOptions(false)}</optgroup><optgroup label="Valley residents">${npcOptions(true)}</optgroup></select></label></div>
      <p class="small">Your choice changes your look, pronouns and a few lines of dialogue — never your abilities, gear or story.</p>
      <div class="menu row"><button class="btn primary" id="go">Begin</button><button class="btn" id="back">Back</button></div></div></div></div>`;
    s.querySelectorAll("[data-mode]").forEach(q=>q.classList.toggle("sel",q.dataset.mode===cfg.mode));
    const prev=()=>{const c=$("#heroPrev"),x=c.getContext("2d");x.imageSmoothingEnabled=false;x.clearRect(0,0,56,72);if(cfg.animal){const img=new Image();img.onload=()=>{if(document.contains(c))x.drawImage(img,0,10,56,52);};img.src="img/animals/animal-"+cfg.animal.slice(-3)+".png";}else{const look=cfg.npcLook||{hair:cfg.hair,coat:cfg.coat,skin:cfg.skin,style:cfg.style};import("./art.js").then(m=>x.drawImage(m.human(look,"down",0),0,0,56,72));}};
    const chooseNpc=id=>{const npc=NPCS[id];if(!npc?.look)return;cfg.npc=id;cfg.npcLook=npc.look;cfg.animal=null;cfg.pres="npc";cfg.name=npc.name;cfg.pron="they";$("#animal").value="";$("#npcChoice").value=id;$("#hname").value=cfg.name;prev();};
    const setP=p=>{cfg.pres=p;s.querySelectorAll("[data-p]").forEach(b=>b.classList.toggle("sel",b.dataset.p===p));$("#custom").hidden=p!=="custom"&&p!=="animal";$("#npcOptions").hidden=p!=="npc";if(p==="npc"){chooseNpc(cfg.npc||PLAYABLE_NPCS[0][0]);return;}cfg.npc=null;cfg.npcLook=null;if(looks[p]){Object.assign(cfg,looks[p]);cfg.animal=null;$("#animal").value="";$("#hname").value=cfg.name;}else{if(p==="custom"){cfg.animal=null;$("#animal").value="";}cfg.pron=p==="animal"?"they":$("#pron").value;cfg.style=$("#hstyle").value;if(p==="animal"&&!cfg.animal){cfg.animal=ANIMALS[0].id;$("#animal").value=cfg.animal;$("#hname").value=ANIMAL_BY_ID[cfg.animal].name;}}prev();};
    s.querySelectorAll("[data-p]").forEach(b=>b.onclick=()=>{ A.sfx("menu"); setP(b.dataset.p); });
    s.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{cfg.mode=b.dataset.mode;s.querySelectorAll("[data-mode]").forEach(q=>q.classList.toggle("sel",q===b));$("#walkOptions").hidden=cfg.mode!=="walk";});$("#walkBiome").onchange=e=>cfg.walkBiome=e.target.value;
    $("#npcChoice").onchange=e=>chooseNpc(e.target.value);
    $("#animal").onchange=e=>{cfg.npc=null;cfg.npcLook=null;cfg.animal=e.target.value||null;if(cfg.animal){cfg.pres="animal";cfg.pron="they";$("#hname").value=ANIMAL_BY_ID[cfg.animal].name;s.querySelectorAll("[data-p]").forEach(q=>q.classList.toggle("sel",q.dataset.p==="animal"));}else{cfg.pres="custom";s.querySelectorAll("[data-p]").forEach(q=>q.classList.toggle("sel",q.dataset.p==="custom"));}$("#npcOptions").hidden=true;prev();};
    s.querySelectorAll(".sw").forEach(b=>b.onclick=()=>{ cfg[b.dataset.k]=b.dataset.v; prev(); });
    $("#pron").onchange=e=>cfg.pron=e.target.value; $("#hstyle").onchange=e=>{ cfg.style=e.target.value; prev(); };
    $("#back").onclick=()=>this.showTitle();
    $("#go").onclick=()=>{ const name=($("#hname").value||"").trim().slice(0,14) || (cfg.pres==="girl"?"Lina":cfg.npc?NPCS[cfg.npc].name:"Rowan");
      const setup={name,pres:cfg.pres,pron:cfg.pron,npc:cfg.npc,friendly:$("#friendlyMode").checked,look:cfg.npcLook||{hair:cfg.hair,coat:cfg.coat,skin:cfg.skin,style:cfg.style,animal:cfg.animal}};
      if(cfg.mode==="story"){this.g.newRun(setup);this.showLevelSelect(()=>this.playIntro());}else if(cfg.mode==="meet")this.g.startMeetGuides(setup);else this.g.startSandbox(setup,cfg.mode,cfg.walkBiome); };
    setP("boy"); this.focusFirst(s); }

  // ---------------- opening scene ----------------
  playIntro(){ this.state="intro"; const s=$("#screen"); s.className="screen intro"; const h=this.g.h;
    const lines = [
      ["storm", "Rain came sideways off the sea. The road home had turned to running water."],
      ["storm", "A gust lifted "+esc(h.name)+" clean off the path, and the shore was gone, and then the sky."],
      ["tree", "Somewhere far from home, a leaning tree. Its roots made a hollow just big enough."],
      ["tree", "The storm walked over all night. The tree held. So did "+(h.pron==="they"?"they":h.pron==="she"?"she":"he")+"."],
      ["dawn", "Morning. A strange beach. A crate washed up in the wrack line. And, inland, a trail."] ];
    let i=0; s.innerHTML=`<canvas id="introArt" width="384" height="224"></canvas><div class="introText" id="itext"></div><div class="introBtns"><button class="btn" id="inext">Next</button><button class="btn" id="iskip">Skip scene</button></div>`;
    const c=$("#introArt"),x=c.getContext("2d"),t0=performance.now();
    const draw=()=>{if(!document.body.contains(c))return;const t=settings.reduceMotion?0:(performance.now()-t0)/1000;drawOpeningScene(x,lines[i]?.[0]||"dawn",t);requestAnimationFrame(draw);};draw();
    const show=()=>{if(i>=lines.length)return this.startPlay();$("#itext").textContent=lines[i][1];};
    $("#inext").onclick=()=>{A.sfx("menu");i++;show();};$("#iskip").onclick=()=>this.startPlay();show();$("#inext").focus(); }

  showLevelSelect(onBegin){const eligible=LEVELS.map(L=>L.n),chosen=eligible[Math.floor(Math.random()*eligible.length)]||1,s=$("#screen");this.state="levelSelect";s.className="screen create";s.hidden=false;s.innerHTML='<div class="card"><h2>Choose a trail</h2><p>Choose a level, or let the valley choose one for you.</p><label>Starting level <select id="levelChoice">'+eligible.map(n=>'<option value="'+n+'" '+(n===chosen?'selected':'')+'>Level '+n+' · '+esc(LEVELS[n-1].name)+'</option>').join("")+'</select></label><div class="menu row"><button class="btn" id="randomLevel">Random level</button><button class="btn primary" id="beginLevel">Begin</button></div></div>';$("#randomLevel").onclick=()=>{$("#levelChoice").value=eligible[Math.floor(Math.random()*eligible.length)]||1;};$("#beginLevel").onclick=()=>{this.g.enterLevel(+$ ("#levelChoice").value,"entry");if(onBegin)onBegin();else this.startPlay();};this.focusFirst(s);}
  setupPlayTools(){ $("#quickSave").onclick=()=>this.saveToFile();$("#perspectiveToggle").onclick=()=>{ settings.mode=settings.mode==="2.5d"?"top":"2.5d"; $("#perspectiveToggle").textContent=settings.mode==="2.5d"?"2D view":"2.5D view"; this.toast(settings.mode==="2.5d"?"2.5D perspective":"Classic top-down"); }; $("#fullscreenToggle").onclick=async()=>{ try{ if(document.fullscreenElement) await document.exitFullscreen(); else await this.root.requestFullscreen(); }catch{ this.toast("Full screen is unavailable in this browser."); } };if(!this._fullscreenBound){this._fullscreenBound=true;document.addEventListener("fullscreenchange",()=>{ $("#fullscreenToggle").textContent=document.fullscreenElement?"Exit full screen":"Full screen"; setTimeout(()=>window.dispatchEvent(new Event("resize")),40); });} }
  startPlay(){this.g.endIntroDemo?.();this.state="play";$("#screen").hidden=true;$("#screen").innerHTML="";$("#hud").hidden=false;$("#sandboxBar").hidden=false;this.updateTouchVis();this.setupPlayTools();if(this.g.run.mode==="meet"){this.updateHUD();this.toast("Explore the forest and find the guides.",true);}else this.levelIntro(this.g.run.lv); }
  startMeetGuides(){this.state="play";$("#banner").classList.remove("show");$("#banner").innerHTML="";$("#screen").hidden=true;$("#screen").innerHTML="";$("#hud").hidden=false;$("#sandboxBar").hidden=false;this.updateTouchVis();this.setupPlayTools();this.updateHUD();this.toast("Explore the forest and find the guides.",true);}
  startSandbox(mode){ this.state="play"; $("#banner").classList.remove("show"); $("#banner").innerHTML=""; $("#screen").hidden=true; $("#screen").innerHTML=""; $("#hud").hidden=false; this.updateTouchVis();this.setupPlayTools(); this.sandboxModeChanged(mode); this.sandboxIntro(mode);
    $("#sandboxToggle").onclick=()=>this.g.toggleMeditation(); $("#sandboxCraft").onclick=()=>this.openCraft("sandbox"); }
  sandboxModeChanged(mode){ $("#sandboxBar").hidden=false; $("#sandboxToggle").textContent=mode==="hearth"?"Change refuge · G":mode==="garden"?"Change refuge · G":"Change refuge · G"; this.updateHUD(); this.toast(mode==="garden"?"You settle into the garden.":mode==="hearth"?"A quiet room, kept warm and open to all.":mode==="walk"?"A new path opens through the "+this.g.run.walkBiome+".":mode==="nature"?"You enter a changing nature reserve.":"You rise into the oldgrowth forest.",true); }
  sandboxIntro(mode){ const box=$("#levelIntro"), garden=mode==="garden",hearth=mode==="hearth",walk=mode==="walk"||mode==="nature",title=mode==="walk"?"Take a Walk · "+this.g.run.walkBiome[0].toUpperCase()+this.g.run.walkBiome.slice(1):mode==="nature"?"Fibonacci Nature Reserve":garden?"A Garden of Your Own":hearth?"The Quiet Hearth":"The Oldgrowth Forest",desc=walk?"Explore a freshly generated landscape, meet residents who know this place, forage, build simple tools, fish by water and cook at a fire.":garden?"Forage seeds, craft a trowel and watering can, prepare a bed, plant, water and wait for crops to ripen.":hearth?"Wander between endlessly re-dressed cozy rooms, talk with a gentle neighbor, rest, and reflect. There is no combat or quest pressure.":"Wander deep woodland, forage North American foods and mushrooms, craft tools, and press G to change your refuge.";this.levelIntroOpen=true;box.hidden=false;box.innerHTML='<section class="levelGuide" role="dialog" aria-modal="true" aria-labelledby="guideTitle"><div class="guideRegion">SANDBOX · '+(walk?"TAKE A WALK":garden?"TEND GARDEN":hearth?"QUIET HEARTH":"EXPLORE FOREST")+'</div><h2 id="guideTitle">'+esc(title)+'</h2><div class="guideObjective">'+desc+'</div><p>'+(hearth?"The keeper shares reflections on hope, gratitude, comfort and peace inspired by Psalms.":walk?"Every route uses a Fibonacci-seeded layout variation. Scroll over the map to zoom.":"Wild foods in the game are not real-world identification advice.")+'</p><div class="guideControls">Move: WASD / arrows · Use: Space · '+(walk?"Double-click finds · scroll to zoom · Escape → Journal.":"G changes your place of retreat.")+'</div><button class="btn primary" id="guideStart">Enter sandbox</button></section>'; $("#guideStart").onclick=()=>{box.hidden=true;this.levelIntroOpen=false;}; $("#guideStart").focus(); }
  tutorial(){ const steps=[["Move with WASD / arrow keys (or the touch pad).", ()=>this.g.p.moving],["Press Space near things to use them — try the crate.", ()=>this.g.M.state.done],["Press Tab for your bag, M for the map, Esc to pause.", ()=>this._openedBag],["Follow the trail east. That's the whole tutorial.", ()=>this.g.run.lv>1]];
    let i=0; const tip=$("#tip"); tip.hidden=false; const next=()=>{ if (i>=steps.length || !settings.hints || this.state==="title") { tip.hidden=true; return; } tip.innerHTML=esc(steps[i][0])+' <button class="mini" id="tipskip">Skip tutorial</button>'; $("#tipskip").onclick=()=>{ i=99; tip.hidden=true; }; };
    next(); const iv=setInterval(()=>{ if (i>=steps.length||this.state==="title") { clearInterval(iv); tip.hidden=true; return; } if (steps[i][1]()) { i++; next(); } },300); }

  // ---------------- HUD ----------------
  updateHUD(){ const g=this.g; if (!g.run) return; const h=g.h, p=g.p, n=g.run.lv, L=g.L;
    const vm=g.vitMax(), bm=g.brMax();
    $("#hpFill").style.width=(100*Math.max(0,h.vit)/vm)+"%"; $("#hpTxt").textContent=Math.max(0,Math.ceil(h.vit))+"/"+vm;
    $("#brFill").style.width=(100*h.br/bm)+"%"; $("#brTxt").textContent=Math.floor(h.br)+"/"+bm;
    $("#xpFill").style.width=(100*h.xp/g.xpNeed())+"%";
    $("#lvlTxt").textContent=g.run.mode==="story"?"Level "+n+" of "+LEVELS.length+" · "+L.name:"Sandbox · "+(g.run.mode==="garden"?"Forest Garden":g.run.mode==="hearth"?"Quiet Hearth · Room "+((g.run.hearthRoom||0)+1):g.run.mode==="walk"?"Walk · "+g.run.walkBiome:g.run.mode==="nature"?"Nature · Fibonacci "+(g.M.fibonacci?.variant+1):g.run.mode==="meet"?"Meet the Gurus":"Oldgrowth Forest"); $("#heroLvl").textContent="Hero Lv "+h.lvl+(h.gp?" (+"+h.gp+" growth)":"");
    $("#sandboxBar").hidden=false;const canChangeRefuge=["forest","garden","hearth","walk","nature"].includes(g.run.mode);$("#sandboxToggle").hidden=!canChangeRefuge;$("#sandboxCraft").hidden=!canChangeRefuge;$("#sandboxToggle").textContent=canChangeRefuge?"Change refuge · G":""; $("#perspectiveToggle").textContent=settings.mode==="2.5d"?"2D view":"2.5D view";
    const t=g.activeTech(); $("#wpn").textContent=g.weapon().name;
    const cd = t ? (p.cds[t]||0) : 0, tot = t?TECHS[t].cd:1; $("#tech").innerHTML = t ? esc(TECHS[t].name)+(cd>0?' <span class="cd">'+cd.toFixed(1)+'s</span>':' <span class="ok">ready</span>') : "—";
    $("#techCd").style.width = t ? (100*(1-cd/tot))+"%" : "0%";
    const st=g.M.state; let obj = L.obj; if (st.done) obj = n===LEVELS.length ? "Walk to the water's edge — or keep exploring." : "Complete! The way east is open.";
    if (g.L.mech==="protect" && st.started && !st.done) obj += " ("+Math.ceil(st.left)+"s)";
    if (g.G && !g.G.done) { $("#boss").hidden=false; $("#bossName").textContent=g.G.def.name; $("#bossHp").style.width=(100*Math.max(0,g.G.hp)/g.G.max)+"%"; $("#bossCalm").style.width=g.G.calm+"%"; } else $("#boss").hidden=true;
    $("#obj").textContent=obj; $("#hint").textContent = this.showHint ? "Hint: "+(HINTS[L.mech]||"") : "";
    if (this._mmT===undefined || performance.now()-this._mmT>250) { this._mmT=performance.now(); drawMinimap($("#minimap"), g); }this.cookingTimer(g.run.cooking?.remaining||0,g.run.cooking?.total||0);
    if (I.inputState.padJustConnected) { I.inputState.padJustConnected=false; this.toast("Controller connected: stick/D-pad move, A interact, X attack, Y technique, B dodge, Start pause."); } }
  combatLog(t){ const c=$("#clog"); const d=el("div",null,esc(t)); c.appendChild(d); while(c.children.length>6) c.firstChild.remove(); }
  levelBanner(n){ const L=LEVELS[n-1], R=REGIONS[Math.floor((n-1)/9)]; const b=$("#banner"); b.innerHTML='<div class="r">'+esc(R.name)+'</div><div class="n">Level '+n+' of ' + LEVELS.length + '</div><div class="t">'+esc(L.name)+'</div>'; b.classList.remove("show"); void b.offsetWidth; b.classList.add("show"); }
  levelIntro(n){ const L=LEVELS[n-1], R=REGIONS[Math.floor((n-1)/9)], box=$("#levelIntro"); if(!box) return; this.levelIntroOpen=true; box.hidden=false; box.innerHTML='<section class="levelGuide" role="dialog" aria-modal="true" aria-labelledby="guideTitle"><div class="guideRegion">'+esc(R.name)+' · LEVEL '+n+'</div><h2 id="guideTitle">'+esc(L.name)+'</h2><div class="guideObjective">'+esc(L.obj)+'</div><p>'+esc(HINTS[L.mech]||"Explore the path and look for things you can use.")+'</p><div class="guideControls">Move: WASD / arrows · Use: Space · Strike: J · Technique: K · Dodge: Shift · Bag: Tab · Map: M</div><button class="btn primary" id="guideStart">Begin Level</button></section>'; $("#guideStart").onclick=()=>{ box.hidden=true; this.levelIntroOpen=false; }; $("#guideStart").focus(); }
  completeCue(n){ const b=$("#cue"); b.textContent="✦ Level "+n+" complete ✦"; b.classList.remove("show"); void b.offsetWidth; b.classList.add("show"); }
  enemyAim(enemy){if(this.panel)return;this.openPanel("A moment to choose",b=>{const name=enemy.d?.name||"The creature";b.innerHTML='<p><b>'+esc(name)+' is gathering itself.</b></p><p class="small">Its next movement is clearly telegraphed. Choose how to meet it.</p><div class="menu row"><button class="btn primary" id="enemyAttack">Attack</button><button class="btn" id="enemyObserve">Observe</button></div>';$("#enemyAttack").onclick=()=>{this.closePanel();this.g.resolveEnemyDecision(enemy,"attack");};$("#enemyObserve").onclick=()=>{this.closePanel();this.g.resolveEnemyDecision(enemy,"observe");};});this.focusFirst($("#panel"));}
  storeAutosave(){try{if(this.g.run)localStorage.setItem("riverTurnsAutosave",this.g.saveJSON(settings));return true;}catch{return false;}}
  continueJourney(){try{const text=localStorage.getItem("riverTurnsAutosave");if(!text||!this.g.loadJSON(text,settings)){this.toast("No compatible journey save was found.");return;}this.closeAll();this.startPlay();this.toast("Journey restored.",true);}catch{this.toast("The saved journey could not be opened.");}}
  saveToFile(){try{const json=this.g.saveJSON(settings),blob=new Blob([json],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="where-the-river-turns-save.json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);localStorage.setItem("riverTurnsAutosave",json);this.toast("Journey saved as a portable JSON file.",true);}catch{this.toast("This browser could not create a save file.");}}
  async loadFile(file){try{const text=await file.text(),apply=()=>{if(!this.g.loadJSON(text,settings)){this.toast("That file is not a compatible River Turns save.");return;}this.closeAll();this.startPlay();this.storeAutosave();this.toast("Journey loaded safely.",true);};if(this.g.run)this.confirm("Importing replaces your active journey. Continue?",apply,()=>this.openSaveLoad());else apply();}catch{this.toast("The save file could not be read.");}}
  openSaveLoad(back){this.openPanel("Save / Load",b=>{b.innerHTML='<p>A portable JSON save includes your inventory, visited places, quests, choices and world state.</p><div class="menu row"><button class="btn primary" id="saveDownload">Download save</button><button class="btn" id="saveUpload">Import save</button></div><p class="small">Importing a valid file replaces the current journey.</p>';$("#saveDownload").onclick=()=>this.saveToFile();$("#saveUpload").onclick=()=>$("#saveImport").click();},{back});}
    openSoundLibrary(back){this.openPanel("Sound Library",b=>{b.innerHTML='<p class="small">A generated soundtrack repository. Modes rotate through the major scale; melodies use Fibonacci-derived scale degrees.</p><h3>Soundtrack</h3>'+SOUNDTRACK.map(t=>'<div class="item"><div><b>'+esc(t.name)+'</b><div class="small">'+esc(t.description)+' Degrees: '+t.degrees.join(", ")+'</div></div><button class="btn mini" data-track="'+t.id+'">Preview</button></div>').join("")+'<h3>Sound effects</h3><div class="menu row">'+Object.entries(SFX_LIBRARY).map(([id,name])=>'<button class="btn mini" data-sfx="'+id+'">'+esc(name)+'</button>').join("")+'</div>';b.querySelectorAll("[data-track]").forEach(x=>x.onclick=()=>A.previewTrack(x.dataset.track));b.querySelectorAll("[data-sfx]").forEach(x=>x.onclick=()=>A.sfx(x.dataset.sfx));},{back});}
  openMapIndex(back){this.openPanel("Map Index",b=>{b.innerHTML=REGIONS.map((region,i)=>'<section class="mapIndexRegion"><h3>'+esc(region.name)+'</h3>'+LEVELS.slice(i*9,i*9+9).map(L=>'<details class="mapIndexEntry"><summary>Level '+L.n+' · '+esc(L.name)+'</summary><canvas class="mapPreview" width="704" height="360" data-map-id="'+L.n+'" aria-label="Map layout for '+esc(L.name)+'"></canvas><p class="small">'+esc(L.obj)+'</p><p>'+esc(L.jr)+'</p></details>').join("")+'</section>').join("");b.querySelectorAll(".mapIndexEntry").forEach(entry=>entry.addEventListener("toggle",()=>{if(entry.open&&!entry.dataset.rendered){drawMapPreview(entry.querySelector("canvas"),+entry.querySelector("canvas").dataset.mapId);entry.dataset.rendered="1";}}));},{back});}
  openReference(back){const animals=ANIMALS.map(a=>({name:a.name,description:a.description,image:"img/animals/animal-"+a.id.slice(-3)+".png"}));const facts={mushroom:"Glowcap is a fictional bioluminescent valley fungus; it is not a real species and does not identify any wild mushroom.",lily:"Water lilies grow from rooted rhizomes in still or slow water. Their broad floating leaves shade the surface and provide shelter for small aquatic life.",blackberry:"Blackberry shrubs have thorny arching canes and aggregate fruits that ripen from red to black. They thrive at woodland edges and disturbed sunny ground; birds and mammals disperse their seeds.",blueberry:"Blueberries grow on low or tall shrubs, often in acidic woodland, heath or bog soils. Their blue bloom is a natural wax coating; many birds and mammals eat the berries.",wild_strawberry:"Wild strawberries are low plants with three toothed leaflets and small red fruits. They spread by runners in sunny openings and woodland edges.",raspberry:"Raspberries grow on woody canes, commonly in sunny clearings. Their aggregate fruit separates from its central core when ripe.",serviceberry:"Serviceberries grow on shrubs or small trees, flower early in spring and bear purple-red fruits in summer. They are important food for birds.",pawpaw:"Pawpaw is an understory tree of rich eastern North American woods. Its large leaves and unusual custard-like fruits are distinctive; flies and beetles pollinate its flowers.",prickly_pear:"Eastern prickly pear is a low cactus of dry, sandy or rocky openings. Flattened pads bear spines and glochids; handle no wild plant without expert knowledge.",wild_plum:"Wild plums grow on thorny shrubs or small trees in sunny thickets. Their spring blossoms feed pollinators before the fruits develop.",cranberry:"Cranberries grow on trailing plants in acidic peatlands and bogs. Their evergreen leaves and tart red fruits suit wet, cool habitats.",wild_grape:"Wild grapevines climb with tendrils and produce clusters of fruit. They grow along woodland margins and provide cover and food for wildlife.",huckleberry:"Huckleberries are shrubs of woodland, heath or mountain habitats. Their dark berries resemble blueberries, but leaf and stem details differ by species.",cattail_shoot:"Cattails grow in shallow freshwater marshes. Their upright sword-shaped leaves and brown flower spikes are characteristic; wetland stands shelter birds and insects.",dandelion_greens:"Dandelions form a basal rosette of toothed leaves and a single yellow flower head. They grow in open ground and provide early-season nectar.",wild_onion:"Wild onions are recognized by onion scent and hollow or flattened leaves, with bulbs below ground. Several toxic plants can be confused with them; scent alone is not a safe identification.",fiddlehead:"Young fern fronds uncoil in spring. A fiddlehead is a growth stage, not a species; fern identification is essential, and some ferns are unsafe to eat.",nettle_tea:"Stinging nettles favor moist, nutrient-rich soil and have opposite toothed leaves with stinging hairs. Their caterpillar-feeding leaves support many butterflies.",rosehip:"Rose hips are the fleshy seed cases of wild roses, often red or orange in autumn. They persist into winter and feed birds and mammals.",morel:"Morels have a deeply honeycombed cap and are usually found in spring near woodland trees. False morels can be dangerously toxic; never identify or eat mushrooms from a game description.",chanterelle:"Chanterelles are woodland fungi with blunt, forked ridges rather than thin blade-like gills, often near trees in summer and autumn. Similar species require expert comparison.",oyster_mushroom:"Oyster mushrooms form overlapping shelves on dead or dying hardwood, with pale gills running down a short off-center stem. They help decompose wood.",chicken_mushroom:"Chicken-of-the-woods forms bright orange shelves with yellow margins on trees or logs. It is a wood-decaying fungus; lookalikes and individual sensitivities make expert identification important.",puffball:"Puffballs are round fungi that release clouds of spores when mature. In very young examples the interior is uniformly white; dangerous immature lookalikes make expert identification essential.",lion_mane:"Lion's mane grows on hardwood as a pale mass of dangling spines, most often on damaged or dead trunks in cool seasons. It is a wood-decaying fungus.",quartz:"Quartz is silicon dioxide, a hard and abundant mineral. Milky white color often comes from microscopic fluid inclusions; veins commonly fill cracks in bedrock.",mica:"Mica minerals split along flat planes into thin, flexible sheets. Their reflective surfaces are common in granite and metamorphic rocks.",stone:"Flint is hard, fine-grained silica. Conchoidal fractures can create sharp edges, which is why flint was historically valued for tools."};const things=Object.entries(ITEMS).map(([k,v])=>({name:v.name,description:facts[k]||v.desc,image:null}));const portrait=look=>{try{return look?human(look,"down",0).toDataURL():null;}catch{return null;}},people=Object.values(NPCS).map(n=>({name:n.name,description:n.fact||n.role+" of the river valley. Speak with them to learn more.",image:portrait(n.look)}));const residents=AMBIENT_NPCS.map(n=>({name:n.name,description:n.role+"; " +n.thought+" "+n.note,image:portrait(n.look)}));const creatures=Object.values(ENEMIES).map(e=>({name:e.name,description:e.note+" Their behavior can be observed before you choose how to respond.",image:null})),guardians=Object.values(GUARDIANS).map(e=>({name:e.name,description:e.desc+" Each guardian can be calmed through patient observation and the region's clues.",image:null}));const entries=[...animals,...creatures,...guardians,...people,...residents,...things,...LEVELS.map(l=>({name:l.name,description:l.jr+" "+l.obj,image:null})),...Array.from({length:50},(_,i)=>({name:"River tree form "+(i+1),description:"A procedural canopy and branch variation within the valley's native tree shapes.",image:(()=>{try{return prop(REGIONS[1],6,i).toDataURL();}catch{return null;}})()}))];let query="";this.openPanel("Field Guide",b=>{b.innerHTML='<label>Find a species, person or object <input id="guideSearch" type="search" placeholder="Search the field guide"></label><div id="guideEntries" class="guideEntries"></div>';const draw=()=>{const q=query.trim().toLowerCase(),host=$("#guideEntries");const filtered=entries.filter(e=>(e.name+" "+e.description).toLowerCase().includes(q));host.innerHTML=filtered.map(e=>'<article class="guideEntry">'+(e.image?'<img src="'+e.image+'" alt="">':'')+'<div><b>'+esc(e.name)+'</b><p class="small">'+esc(e.description)+'</p></div></article>').join("")||'<p class="small">No entries match that search.</p>';};$("#guideSearch").value=query;$("#guideSearch").oninput=e=>{query=e.target.value;draw();};draw();},{back});}
  inspect(name,desc){const tip=$("#tileTip");tip.textContent=name+" — "+desc;tip.hidden=false;tip.style.left="12px";tip.style.top="auto";tip.style.bottom="88px";}
  toast(t, big){ const d=el("div","toast"+(big?" big":""),esc(t)); this.toasts.appendChild(d); setTimeout(()=>d.classList.add("out"), big?3600:2300); setTimeout(()=>d.remove(), big?4200:2900); while(this.toasts.children.length>5) this.toasts.firstChild.remove(); }
  levelTransition(from,to,cb){const source=LEVELS[from-1],destination=LEVELS[to-1];if(!source||!destination)return cb?.();const s=$("#screen");this._transitionToken=(this._transitionToken||0)+1;const token=this._transitionToken,previous=this.state,wasHidden=s.hidden;s.className="screen mapTransition";s.hidden=false;s.innerHTML='<canvas id="transitionArt" width="384" height="224" aria-hidden="true"></canvas><div class="transitionLabels" role="group" aria-label="Map transition"><div class="transitionPlace"><small>Leaving · Level '+from+'</small>'+esc(source.name)+'</div><div class="transitionStop" aria-hidden="true">→</div><div class="transitionPlace"><small>Arriving · Level '+to+'</small>'+esc(destination.name)+'</div><button class="btn primary transitionContinue" id="transitionContinue">Continue</button></div>';const ctx=$("#transitionArt").getContext("2d");let start=null,finished=false;this.state="transition";this.fading=true;const finish=()=>{if(finished||token!==this._transitionToken)return;finished=true;s.onclick=null;s.hidden=wasHidden;s.innerHTML="";this.state=previous;this.fading=false;cb?.();};s.onclick=finish;$("#transitionContinue").onclick=e=>{e.stopPropagation();finish();};const frame=now=>{if(token!==this._transitionToken||finished)return;if(start===null)start=now;drawTransitionScene(ctx,source,destination,settings.reduceMotion?0:(now-start)/1000);requestAnimationFrame(frame);};requestAnimationFrame(frame);this.focusFirst(s);}
  fade(cb){ if (this.fading) return; this.fading=true; const f=$("#fade"); f.classList.add("on"); setTimeout(()=>{ try{ cb(); } finally { f.classList.remove("on"); setTimeout(()=>this.fading=false, 250); } }, settings.reduceMotion?60:300); }

  // ---------------- dialogue ----------------
  dialog(script, npc, onEnd){ if (this.dlg) { this.dlg.queue.push(...script); return; } this.dlg = { queue:[...script], onEnd }; I.clearPressed(); $("#dlg").hidden=false; this.nextStep(); }
  speakerName(sp){ if (sp==="Blue") return this.g.run.flags.met_aster ? "Aster" : "Traveler in the Blue Coat"; return sp; }
  nextStep(){ const d=this.dlg; if (!d) return; const api=this.g.api();
    while (d.queue.length && d.queue[0].do) { const s=d.queue.shift(); s.do(api); if (!this.dlg) return; }
    if (!d.queue.length) return this.endDialog();
    const s=d.queue.shift(); const box=$("#dlg");
    if (typeof s==="string") { const [sp, ...rest]=s.split("|"); const txt=this.g.fill(rest.join("|"));
      $("#dlgName").textContent = sp ? this.speakerName(sp) : ""; $("#dlgName").hidden = !sp; $("#dlgChoices").innerHTML=""; $("#dlgMore").hidden=false;
      d.full=txt; d.shown=0; d.typing = settings.typewriter; if (!d.typing) $("#dlgText").textContent=txt; else $("#dlgText").textContent="";
      d.mode="line"; }
    else if (s.choice) { d.mode="choice"; $("#dlgMore").hidden=true; const c=$("#dlgChoices"); c.innerHTML="";
      s.choice.forEach((ch,i)=>{ const b=el("button","btn choice",(i+1)+". "+esc(this.g.fill(ch.t))); b.onclick=()=>{ A.sfx("menu"); c.innerHTML=""; if (ch.do) ch.do(api); if (!this.dlg) return; if (ch.next) d.queue.unshift(...ch.next); this.nextStep(); }; c.appendChild(b); });
      setTimeout(()=>{ const f=c.querySelector("button"); f&&f.focus(); },20); }
    else this.nextStep(); }
  tickDialog(dt){ const d=this.dlg; if (!d) return; if (d.mode==="line" && d.typing) { d.shown += dt*settings.textSpeed; const n=Math.min(d.full.length, Math.floor(d.shown)); $("#dlgText").textContent=d.full.slice(0,n); if (n>=d.full.length) d.typing=false; }
    if (d.mode==="line" && (I.consume("interact")||I.consume("attack"))) this.advance(); }
  advance(){ const d=this.dlg; if (!d) return; if (d.mode!=="line") return; if (d.typing) { d.typing=false; $("#dlgText").textContent=d.full; return; } A.sfx("menu"); this.nextStep(); }
  skipDialog(){ const d=this.dlg; if (!d) return; const api=this.g.api(); if (d.mode==="choice") return;
    while (d.queue.length && !d.queue[0].choice) { const s=d.queue.shift(); if (s.do) { s.do(api); if (!this.dlg) return; } } this.nextStep(); }
  endDialog(){ const d=this.dlg; this.dlg=null; $("#dlg").hidden=true; I.clearPressed(); d && d.onEnd && d.onEnd(); }

  // ---------------- panels ----------------
  openPanel(title, build, opts={}){ const P=$("#panel"); P.hidden=false; P.innerHTML='<div class="pcard"><div class="phead"><h2>'+esc(title)+'</h2><button class="btn mini" id="pclose" aria-label="Close">✕ Close</button></div><div class="pbody" id="pbody"></div></div>';
    this.panel = { title, build, back:opts.back }; $("#pclose").onclick=()=>this.closePanel(); build($("#pbody")); this.focusFirst(P); I.clearPressed(); }
  refresh(){ if (this.panel) { const b=$("#pbody"); const st=b.scrollTop; b.innerHTML=""; this.panel.build(b); b.scrollTop=st; } }
  closePanel(){ const back=this.panel&&this.panel.back; $("#panel").hidden=true; $("#panel").innerHTML=""; this.panel=null; I.clearPressed(); if (back) back(); }
  closeAll(){ if (this.dlg) { this.dlg=null; $("#dlg").hidden=true; } $("#panel").hidden=true; $("#levelIntro").hidden=true; $("#sandboxBar").hidden=true; this.levelIntroOpen=false; this.panel=null; }
  focusFirst(r){ setTimeout(()=>{ const b=r.querySelector("button.primary, button:not([disabled]), input, select"); b&&b.focus&&b.focus(); },30); }
  menuNav(){ // keyboard / pad navigation inside DOM menus
    const host = this.levelIntroOpen ? $("#levelIntro") : this.panel ? $("#panel") : (this.dlg && this.dlg.mode==="choice") ? $("#dlgChoices") : (this.state!=="play" ? $("#screen") : null); if (!host) return;
    const items=[...host.querySelectorAll("button:not([disabled]), input, select")].filter(e=>e.offsetParent!==null); if (!items.length) return;
    const i=items.indexOf(document.activeElement);
    const inText = document.activeElement && (document.activeElement.tagName==="INPUT"||document.activeElement.tagName==="SELECT");
    if (I.consume("down")||(!inText&&I.consume("right"))) { items[(i+1)%items.length].focus(); A.sfx("menu"); }
    if (I.consume("up")||(!inText&&I.consume("left"))) { items[(i-1+items.length)%items.length].focus(); A.sfx("menu"); }
    if (I.consume("interact") && i>=0 && items[i].tagName==="BUTTON") items[i].click(); }

  openPause(){ this.openPanel("Paused", b=>{ const L=this.g.L;
    b.innerHTML='<p class="small">'+(this.g.run.mode==="story"?'Level '+L.n+' of '+LEVELS.length+' · '+esc(L.name):'Sandbox · '+esc(L.name))+'</p><div class="menu">'+["Resume","Inventory","Journal","Map","Field Guide","Save / Load","Settings","Controls","Reset Run","Return to Title"].map((t,i)=>'<button class="btn'+(i?"":" primary")+'" data-i="'+i+'">'+t+'</button>').join("")+'</div>';
    b.querySelectorAll("[data-i]").forEach(x=>x.onclick=()=>{ const i=+x.dataset.i; A.sfx("menu"); const back=()=>this.openPause();
      if (i===0) this.closePanel(); if (i===1) this.openInventory(back); if (i===2) this.openJournal(back); if (i===3) this.openMap(back); if (i===4) this.openReference(back); if (i===5) this.openSaveLoad(back); if (i===6) this.openSettings(back); if (i===7) this.openControls(back);
      if (i===8) this.confirm("Reset Run? This clears the current journey and returns to the title.", ()=>{ this.g.run=null;try{localStorage.removeItem("riverTurnsAutosave");}catch{}this.showTitle(); }, back);
      if (i===9) this.confirm("Return to Title? Your journey will be kept for Continue Journey.", ()=>{ this.storeAutosave();this.showTitle(); }, back); }); }); }
  confirm(msg, yes, no){ this.openPanel("Are you sure?", b=>{ b.innerHTML='<p>'+esc(msg)+'</p><div class="menu row"><button class="btn primary" id="cy">Yes</button><button class="btn" id="cn">No</button></div>'; $("#cy").onclick=()=>{ this.closePanel(); yes(); }; $("#cn").onclick=()=>{ this.closePanel(); no&&no(); }; }); }

  // ---------------- inventory / equipment / growth ----------------
  openInventory(back){ this._openedBag=true; let tab="weapons";
    this.openPanel("Bag & Gear", b=>{ const g=this.g, h=g.h; const tabs=["weapons","charms","growth","materials","food","tools","keepsakes"];
      b.innerHTML='<div class="tabs">'+tabs.map(t=>'<button class="btn tab'+(t===tab?" sel":"")+'" data-t="'+t+'">'+t[0].toUpperCase()+t.slice(1)+'</button>').join("")+'</div><div id="tabBody"></div>';
      b.querySelectorAll("[data-t]").forEach(x=>x.onclick=()=>{ tab=x.dataset.t; this.refresh(); });
      const tb=$("#tabBody"); let html="";
      if (tab==="weapons") { html='<p class="small">One weapon at a time. Each suits a different way of moving through trouble.</p>';
        for (const [k,w] of Object.entries(WEAPONS)) { const own=h.weapons.has(k); html+='<div class="item'+(own?"":" locked")+'"><div><b>'+esc(w.name)+'</b>'+(h.weapon===k?' <span class="tag">equipped</span>':'')+'<div class="small">'+(own?esc(w.desc):"Not yet found.")+'</div>'+(own?'<div class="stats">Power '+w.dmg+' · Reach '+w.reach+' · Speed '+(1/w.cd).toFixed(1)+'/s · Stagger '+w.stagger+' · Calming ×'+w.calm+(w.ranged?' · Breath '+w.breath+'/shot':'')+'</div>':'')+'</div>'+(own&&h.weapon!==k?'<button class="btn mini" data-w="'+k+'">Equip</button>':'')+'</div>'; } }
      if (tab==="charms") { html='<p class="small">Two charm slots. Slot 1: '+(h.charms[0]?esc(CHARMS[h.charms[0]].name):"empty")+' · Slot 2: '+(h.charms[1]?esc(CHARMS[h.charms[1]].name):"empty")+'</p>';
        for (const [k,c] of Object.entries(CHARMS)) { const own=h.charmsOwned.has(k), on=h.charms.includes(k); html+='<div class="item'+(own?"":" locked")+'"><div><b>'+esc(c.name)+'</b>'+(on?' <span class="tag">worn</span>':'')+'<div class="small">'+(own?esc(c.desc):"Not yet found or crafted.")+'</div></div>'+(own?(on?'<button class="btn mini" data-un="'+k+'">Remove</button>':'<button class="btn mini" data-c="'+k+'" data-s="0">Slot 1</button><button class="btn mini" data-c="'+k+'" data-s="1">Slot 2</button>'):'')+'</div>'; } }
      if (tab==="growth") { const S=[["power","Power","Basic attack strength."],["guard","Guard","Reduces harm taken."],["att","Attunement","Technique strength and calming."],["poise","Poise","Faster recovery, less interruption."]];
        html='<div class="statgrid"><div>Vitality <b>'+Math.ceil(h.vit)+'/'+g.vitMax()+'</b></div><div>Breath <b>'+Math.floor(h.br)+'/'+g.brMax()+'</b></div><div>Hero level <b>'+h.lvl+'</b></div><div>XP <b>'+h.xp+'/'+g.xpNeed()+'</b></div></div><p>Growth points: <b>'+h.gp+'</b>'+(h.gp?"":" (earn one each hero level)")+'</p>';
        for (const [k,n,d] of S) html+='<div class="item"><div><b>'+n+' '+g.stat(k)+'</b> <span class="small">('+h.alloc[k]+' placed)</span><div class="small">'+d+'</div></div><button class="btn mini" data-g="'+k+'" '+(h.gp?"":"disabled")+'>+1</button></div>';
        html+='<p class="small">Rethink your growth (respec) at any rest fire or hub.</p><h3>Techniques</h3>'; for (const [k,t] of Object.entries(TECHS)) html+='<div class="item'+(h.techs.has(k)?"":" locked")+'"><div><b>'+esc(t.name)+'</b> <span class="small">'+t.cost+' Breath · '+t.cd+'s cooldown</span><div class="small">'+(h.techs.has(k)?esc(t.desc):"Not yet learned.")+'</div></div></div>'; }
      if (tab==="tools") { const tools=[...g.run.tools]; html=tools.length?tools.map(k=>'<div class="item"><div><b>'+esc(ITEMS[k].name)+'</b>'+(h.selectedItem===k?' <span class="tag">in hand</span>':'')+'<div class="small">'+esc(ITEMS[k].desc)+'</div></div><button class="btn mini" data-hold="'+k+'">'+(h.selectedItem===k?'Held':'Hold')+'</button></div>').join(""):'<p class="small">No tools crafted yet.</p>'; }
      if(tab==="keepsakes"){const found=[...g.run.mapFinds].sort((a,b)=>a-b);html='<div class="item cur"><div><b>Trail Keepsakes · '+found.length+' / '+LEVELS.length+'</b><div class="small">One hidden keepsake in every story map.</div></div></div>';if(found.length)html+=found.map(id=>'<div class="item"><b>'+esc(LEVELS[id-1]?.name||"Unknown trail")+' Keepsake</b><span class="tag">found</span></div>').join("");}
      if (["materials","food","keepsakes"].includes(tab)) { const list=Object.entries(h.inv).filter(([k])=>ITEMS[k]&&ITEMS[k].cat===tab); if (!list.length&&tab!=="keepsakes") html='<p class="small">Nothing here yet.</p>';
        for (const [k,n] of list) html+='<div class="item"><div><b>'+esc(ITEMS[k].name)+'</b> ×'+n+(h.selectedItem===k?' <span class="tag">in hand</span>':'')+'<div class="small">'+esc(ITEMS[k].desc)+'</div></div><div class="menu row">'+(tab==="food"?'<button class="btn mini" data-f="'+k+'">Eat</button>':'')+'<button class="btn mini" data-hold="'+k+'">'+(h.selectedItem===k?'Held':'Hold')+'</button></div></div>'; }
      tb.innerHTML=html;
      tb.querySelectorAll("[data-w]").forEach(x=>x.onclick=()=>{ h.weapon=x.dataset.w; A.sfx("menu"); this.toast("Equipped "+WEAPONS[h.weapon].name); this.refresh(); });
      tb.querySelectorAll("[data-c]").forEach(x=>x.onclick=()=>{ const k=x.dataset.c, s=+x.dataset.s; h.charms[s]=k; if (h.charms[1-s]===k) h.charms[1-s]=null; h.vit=Math.min(h.vit,g.vitMax()); A.sfx("menu"); this.refresh(); });
      tb.querySelectorAll("[data-un]").forEach(x=>x.onclick=()=>{ h.charms=h.charms.map(c=>c===x.dataset.un?null:c); h.vit=Math.min(h.vit,g.vitMax()); this.refresh(); });
      tb.querySelectorAll("[data-g]").forEach(x=>x.onclick=()=>{ g.allocate(x.dataset.g); this.refresh(); });
      tb.querySelectorAll("[data-f]").forEach(x=>x.onclick=()=>{ g.useFood(x.dataset.f); this.refresh(); });
      tb.querySelectorAll("[data-hold]").forEach(x=>x.onclick=()=>{h.selectedItem=h.selectedItem===x.dataset.hold?null:x.dataset.hold;this.toast(h.selectedItem?"Holding "+ITEMS[h.selectedItem].name:"Hands free.");this.refresh();});
    }, {back}); }
  openRespec(){ this.openPanel("Rethink Growth", b=>{ const h=this.g.h; const tot=Object.values(h.alloc).reduce((a,c)=>a+c,0);
    b.innerHTML='<p>Placed points: '+tot+'. Free points: '+h.gp+'.</p><p class="small">Gather your growth back and place it again however suits you now.</p><div class="menu row"><button class="btn primary" id="rs">Return all points</button><button class="btn" id="rg">Open growth page</button></div>';
    $("#rs").onclick=()=>{ this.g.respec(); this.refresh(); }; $("#rg").onclick=()=>{ this.closePanel(); this.openInventory(); }; }); }
  openCraft(where){ this.openPanel("Crafting", b=>{ const g=this.g, h=g.h; const list=RECIPES.filter(r=>r.where==="any"||r.where===where||(where==="hub"&&r.where!=="mira")||(where==="mira"&&r.where==="mira"));
    let html='<p class="small">'+(where==="mira"?"Mira's workbench. She watches, mostly.":where==="hub"?"A good workbench and patient company.":"A flat stone and steady hands.")+'</p>';
    for (const r of list){ const done = (r.out.charm&&h.charmsOwned.has(r.out.charm))||(r.out.weapon&&h.weapons.has(r.out.weapon))||(r.out.tool&&g.run.tools.has(r.out.tool)); const ok=!done && Object.entries(r.need).every(([k,n])=>(h.inv[k]||0)>=n);
      const desc = r.out.charm?CHARMS[r.out.charm].desc : r.out.weapon?WEAPONS[r.out.weapon].desc : r.out.tool?ITEMS[r.out.tool].desc : ITEMS[r.out.item].desc;
      html+='<div class="item'+(done?" locked":"")+'"><div><b>'+esc(r.label)+'</b>'+(done?' <span class="tag">owned</span>':'')+'<div class="small">'+esc(desc)+'</div><div class="stats">Needs: '+Object.entries(r.need).map(([k,n])=>ITEMS[k].name+' '+(h.inv[k]||0)+'/'+n).join(", ")+'</div></div><button class="btn mini" data-r="'+r.id+'" '+(ok?"":"disabled")+'>Craft</button></div>'; }
    b.innerHTML=html; b.querySelectorAll("[data-r]").forEach(x=>x.onclick=()=>{ g.craft(x.dataset.r); this.refresh(); }); }); }
  openCooking(back){const recipes=[{raw:"river_fish",out:"cooked_fish",seconds:8,label:"Cook river fish"},{raw:"berry",out:"roasted_berry",seconds:5,label:"Warm berries"}];this.openPanel("Campfire cooking",b=>{b.innerHTML='<p>Choose an ingredient. Cooking takes real game seconds; your food is held until it is ready.</p>'+recipes.map(r=>'<div class="item"><div><b>'+esc(r.label)+'</b><div class="small">'+r.seconds+' seconds · '+esc(ITEMS[r.out].desc)+' · You have '+(this.g.h.inv[r.raw]||0)+'</div></div><button class="btn mini" data-cook="'+r.raw+'" '+(this.g.h.inv[r.raw]?"":"disabled")+'>Cook</button></div>').join("");b.querySelectorAll("[data-cook]").forEach(x=>x.onclick=()=>{const r=recipes.find(q=>q.raw===x.dataset.cook);if(this.g.beginCooking(r.raw,r.out,r.seconds))this.closePanel();});},{back});}
  cookingTimer(remaining,total){const el=$("#cookTimer");if(!el)return;el.hidden=!this.g?.run?.cooking;if(!el.hidden)el.textContent="At the fire · "+Math.ceil(remaining)+"s";}
  openShop(){ const T=[ {give:{copperleaf:2},get:"broth",n:1},{give:{shell:1},get:"berry",n:2},{give:{reed:2},get:"tea",n:2},{give:{charcoal:1,copperleaf:1},get:"clay",n:2},{give:{fiber:1},get:"driftwood",n:1},{give:{copperleaf:3},get:"glowseed",n:1} ];
    this.openPanel("Dov's Trades", b=>{ const h=this.g.h; b.innerHTML='<p class="small">“Fair trades only. Well. Mostly fair.”</p>'+T.map((t,i)=>{ const ok=Object.entries(t.give).every(([k,n])=>(h.inv[k]||0)>=n); return '<div class="item"><div>'+Object.entries(t.give).map(([k,n])=>n+" "+ITEMS[k].name).join(" + ")+' → <b>'+t.n+' '+ITEMS[t.get].name+'</b></div><button class="btn mini" data-t="'+i+'" '+(ok?"":"disabled")+'>Trade</button></div>'; }).join("");
      b.querySelectorAll("[data-t]").forEach(x=>x.onclick=()=>{ const t=T[+x.dataset.t]; for (const k in t.give) this.g.take(k,t.give[k]); this.g._noBonus=true; this.g.give(t.get,t.n); this.g._noBonus=false; this.refresh(); }); }); }

  // ---------------- journal ----------------
  openJournal(back){ let tab="story"; this.openPanel("Journal", b=>{ const g=this.g, r=g.run, F=r.flags; const tabs=["story","side quests","techniques","creatures","log","my notes"];
    b.innerHTML='<div class="tabs">'+tabs.map(t=>'<button class="btn tab'+(t===tab?" sel":"")+'" data-t="'+t+'">'+t[0].toUpperCase()+t.slice(1)+'</button>').join("")+'</div><div id="tabBody"></div>';
    b.querySelectorAll("[data-t]").forEach(x=>x.onclick=()=>{ tab=x.dataset.t; this.refresh(); }); let html="";
    if (tab==="story") { const cur=g.L;if(r.mode==="story"){html='<div class="item cur"><div><b>Now: Level '+cur.n+' — '+esc(cur.name)+'</b><div>'+esc(cur.obj)+'</div><button class="btn mini" id="hintBtn">'+(this.showHint?"Hide hint":"Show hint")+'</button></div></div>';for(let n=LEVELS.length;n>=1;n--)if(r.visited.has(n)){const L=LEVELS[n-1];html+='<div class="item"><div><b>'+(r.completed.has(n)?"✓ ":"○ ")+'Level '+n+': '+esc(L.name)+'</b><div class="small">'+esc(g.fill(L.jr))+'</div></div></div>';}}else{html='<div class="item cur"><div><b>Now: '+esc(cur.name)+'</b><div>'+esc(cur.obj)+'</div>'+(g.M.fibonacci?'<div class="small">Fibonacci layout '+(g.M.fibonacci.variant+1)+' of 50.</div>':'')+'</div></div><div class="item"><b>Trail notes</b><div class="small">Trees cut: '+(F.trees_cut||0)+' · Fish caught: '+(F.fish_caught||0)+' · Tools crafted: '+[...r.tools].map(k=>esc(ITEMS[k]?.name||k)).join(", ")+'</div></div>';}}
    if(tab==="side quests"&&r.mode!=="story")html='<div class="item"><b>Trail activities</b><div class="small">Trees cut: '+(F.trees_cut||0)+' · Fish caught: '+(F.fish_caught||0)+' · Enjoy the landscape at your own pace.</div></div>';
    if (tab==="side quests"&&r.mode==="story") { const Q=[
        ["Tangled Gull", F.gull_freed?"done":r.visited.has(3)?"active":null, "Free the gull at Saltgrass Bend."],
        ["Tovan's Foxglove", F.tovan_done?"done":F.met_tovan?"active":null, "Bring Tovan three foxglove sprigs."],
        ["Windfall for the Highlands", F.orchard_done?"done":r.visited.has(30)?"active":null, "Six apples for Hesk's families."],
        ["A Cold Kiln", F.kiln_lit?"done":F.met_pella?"active":null, "Charcoal, vents, then fire — in that order."],
        ["The Hurt Hare", F.hare_done?"done":r.visited.has(51)?"active":null, "Three sweetberries for a hare on Whitebark Trail."],
        ["Gentle with Hares", (F.hares_calmed||0)>=2?"done":r.visited.has(46)?"active":null, "Calm frost hares instead of chasing them ("+(F.hares_calmed||0)+"/2)."],
        ["Nim's Kites", F.kites_done?"done":F.met_nim?"active":null, "Four kites scattered across the islets."],
        ["The Great Heron", F.heron_calm?"done":r.visited.has(60)?"active":null, "Stand quietly near the heron at the crossing."],
        ["Seli's Orchard", F.beds_done?"done":F.met_seli?"active":null, "Plant three old seeds underground."],
        ["Travelers on the Road", F.trav_a&&F.trav_b&&F.trav_c?"done":r.visited.has(74)?"active":null, "Help Brisk, Lowe and Pipkin."],
        ["The Blue Coat", F.met_aster?"done":F.blue1?"active":null, "Conversations with a stranger: "+["blue1","blue2","blue3","blue4"].filter(k=>F[k]).length+"/4 heard."],
        ["Hidden Caches", r.caches>=20?"done":"active", "Caches found: "+r.caches+". Scenic spots: "+r.scenic+"."] ];
      for (const [t,s,d] of Q) if (s) html+='<div class="item"><div><b>'+(s==="done"?"✓ ":"○ ")+esc(t)+'</b><div class="small">'+esc(d)+'</div></div></div>'; }
    if (tab==="techniques") for (const [k,t] of Object.entries(TECHS)) if (g.h.techs.has(k)) html+='<div class="item"><div><b>'+esc(t.name)+'</b><div class="small">'+esc(t.desc)+'</div></div></div>';
    if (tab==="creatures") { for (const k of r.bestiary) html+='<div class="item"><div><b>'+esc(ENEMIES[k].name)+'</b><div class="small">'+esc(ENEMIES[k].note)+'</div></div></div>'; html+='<p class="small">Calmed: '+r.calmed+' · Withdrew after a fight: '+r.defeated+'</p>'; if (!r.bestiary.size) html='<p class="small">No creatures noted yet.</p>'; }
    if (tab==="log") html='<p class="small">Recent events</p>'+r.log.slice().reverse().map(t=>'<div class="small">· '+esc(t)+'</div>').join("");
    if(tab==="my notes")html='<label for="journalNotes">Your notes</label><textarea id="journalNotes" rows="12" maxlength="12000" placeholder="Write anything you would like to remember...">'+esc(r.journalText||"")+'</textarea><p class="small">Notes are included in your save file.</p>';
    $("#tabBody").innerHTML=html; const hb=$("#hintBtn"); if (hb) hb.onclick=()=>{ this.showHint=!this.showHint; this.refresh(); };const notes=$("#journalNotes");if(notes){notes.oninput=()=>{r.journalText=notes.value;};notes.onblur=()=>this.storeAutosave();}
  }, {back}); }

  // ---------------- map ----------------
  openMap(back){ if(this.g.run.mode!=="story"){this.openPanel("Sandbox Map",b=>{b.innerHTML='<canvas id="sandboxMap" width="704" height="512"></canvas><p class="small">'+esc(this.g.L.name)+' · Explored ground only.</p>';drawMinimap($("#sandboxMap"),this.g);},{back});return;} let sel=Math.floor((this.g.run.lv-1)/9); this.openPanel("Valley Map", b=>{ const r=this.g.run;
    let html='<div class="tabs">'+REGIONS.map((R,i)=>{ const seen=[...Array(9)].some((_,j)=>r.visited.has(i*9+j+1)); return '<button class="btn tab'+(i===sel?" sel":"")+'" data-r="'+i+'" '+(seen?"":"disabled")+'>'+(seen?esc(R.name):"???")+'</button>'; }).join("")+'</div>';
    html+='<div class="mapgrid">'; for (let j=0;j<9;j++){ const n=sel*9+j+1, L=LEVELS[n-1]; const v=r.visited.has(n), c=r.completed.has(n), cur=r.lv===n;
      html+='<div class="mcell'+(cur?" cur":"")+(c?" done":"")+(v?"":" unk")+'"><div class="mn">'+(c?"✓":cur?"◉":v?"○":"·")+' '+n+'</div><div class="mt">'+(v?esc(L.name):"Undiscovered")+(L.rest&&v?' <span title="rest place">🔥</span>':'')+(L.hub&&v?' <span class="tag">hub</span>':'')+'</div>'+(v&&!cur?'<button class="btn mini" data-go="'+n+'">Travel</button>':'')+'</div>'; }
    html+='</div><p class="small">✓ complete · ◉ you are here · ○ visited · 🔥 rest place. Travel returns you to any place you have visited.</p>';
    b.innerHTML=html; b.querySelectorAll("[data-r]").forEach(x=>x.onclick=()=>{ sel=+x.dataset.r; this.refresh(); });
    b.querySelectorAll("[data-go]").forEach(x=>x.onclick=()=>{ const n=+x.dataset.go; this.closePanel(); this.panel=null; $("#panel").hidden=true; this.g.travel(n); }); }, {back}); }

  // ---------------- settings & controls ----------------
  openSettings(back){ this.openPanel("Settings", b=>{ const S=settings;
    const row=(label,ctl)=>'<div class="srow"><span>'+label+'</span>'+ctl+'</div>';
    b.innerHTML = row("Display mode",'<div class="menu row"><button class="btn mini'+(S.mode==="top"?" sel":"")+'" data-mode="top">Classic Top-Down</button><button class="btn mini'+(S.mode==="2.5d"?" sel":"")+'" data-mode="2.5d">2.5D World</button></div>')
      + row("Faux-3D terrain relief (2.5D)",'<input type="checkbox" id="s_relief" '+(S.relief?"checked":"")+'>')
      + row("Music volume",'<input type="range" id="s_music" min="0" max="1" step="0.05" value="'+S.music+'">') + row("Sound volume",'<input type="range" id="s_sfx" min="0" max="1" step="0.05" value="'+S.sfx+'">')
      + row("Mute all",'<input type="checkbox" id="s_mute" '+(S.muted?"checked":"")+'>')
      + row("Text size",'<select id="s_text"><option value="1">Normal</option><option value="1.2">Large</option><option value="1.45">Larger</option></select>')
      + row("Typewriter text",'<input type="checkbox" id="s_type" '+(S.typewriter?"checked":"")+'>') + row("Text speed",'<input type="range" id="s_speed" min="15" max="120" step="5" value="'+S.textSpeed+'">')
      + row("Reduce motion",'<input type="checkbox" id="s_rm" '+(S.reduceMotion?"checked":"")+'>') + row("Reduce flashing",'<input type="checkbox" id="s_rf" '+(S.reduceFlash?"checked":"")+'>')
      + row("High-contrast interface",'<input type="checkbox" id="s_hc" '+(S.highContrast?"checked":"")+'>')
      + row("Touch controls",'<select id="s_touch"><option value="auto">Auto</option><option value="on">Show</option><option value="off">Hide</option></select>')
      + row("Tutorial hints",'<input type="checkbox" id="s_hints" '+(S.hints?"checked":"")+'>') + row("Combat log",'<input type="checkbox" id="s_log" '+(S.log?"checked":"")+'>')
      + '<div class="menu row"><button class="btn" id="s_ctrl">Controls & remapping</button></div><p class="small">Settings last for this session only and are never stored.</p>';
    $("#s_text").value=String(S.textSize); $("#s_touch").value=S.touch;
    b.querySelectorAll("[data-mode]").forEach(x=>x.onclick=()=>{ S.mode=x.dataset.mode; this.toast(S.mode==="2.5d"?"2.5D World view":"Classic Top-Down view"); this.refresh(); });
    const on=(id,fn)=>{ $(id).oninput=$(id).onchange=e=>{ fn(e.target); this.applySettings(); }; };
    on("#s_relief",t=>S.relief=t.checked); on("#s_music",t=>S.music=+t.value); on("#s_sfx",t=>S.sfx=+t.value); on("#s_mute",t=>S.muted=t.checked); on("#s_text",t=>S.textSize=+t.value);
    on("#s_type",t=>S.typewriter=t.checked); on("#s_speed",t=>S.textSpeed=+t.value); on("#s_rm",t=>S.reduceMotion=t.checked); on("#s_rf",t=>S.reduceFlash=t.checked); on("#s_hc",t=>S.highContrast=t.checked);
    on("#s_touch",t=>S.touch=t.value); on("#s_hints",t=>S.hints=t.checked); on("#s_log",t=>S.log=t.checked);
    $("#s_ctrl").onclick=()=>this.openControls(()=>this.openSettings(back)); }, {back}); }
  applySettings(){ const S=settings; A.setVolume("music",S.music); A.setVolume("sfx",S.sfx); A.setVolume("muted",S.muted); document.documentElement.style.setProperty("--ts", S.textSize);
    document.body.classList.toggle("hc", S.highContrast); document.body.classList.toggle("rm", S.reduceMotion); $("#clog").hidden=!S.log; this.updateTouchVis(); }
  updateTouchVis(){ const t=settings.touch, show = t==="on" || (t==="auto" && ("ontouchstart" in window || navigator.maxTouchPoints>0)); $("#touch").hidden = !(show && this.state==="play"); }
  openControls(back){ this.openPanel("Controls", b=>{ let html='<p class="small">Click a key to rebind it, then press the new key (Esc cancels).</p><div class="ctrls">';
    for (const a of I.ACTIONS) html+='<div class="srow"><span>'+I.LABELS[a]+'</span><span>'+I.binds[a].map((c,i)=>'<button class="btn mini key" data-a="'+a+'" data-s="'+i+'">'+esc(I.keyName(c))+'</button>').join(" ")+(I.binds[a].length<2?'<button class="btn mini key" data-a="'+a+'" data-s="'+I.binds[a].length+'">+</button>':'')+'</span></div>';
    html+='</div><div class="menu row"><button class="btn" id="rb">Restore defaults</button></div><h3>Controller</h3><p class="small">Stick / D-pad: move · A: interact · X: attack · Y or RT: technique · B or RB: dodge · LB: switch technique · Back: map · LT: bag · Start: pause</p><h3>Touch</h3><p class="small">Drag the left pad to move. Buttons on the right: ✦ use, ⚔ attack, ◆ technique, » dodge, ⟳ switch, ☰ pause.</p>';
    b.innerHTML=html; b.querySelectorAll(".key").forEach(x=>x.onclick=()=>{ x.textContent="press a key…"; I.captureNext(code=>{ if (code) I.bindKey(x.dataset.a, code, +x.dataset.s); this.refresh(); }); });
    $("#rb").onclick=()=>{ I.resetBinds(); this.refresh(); }; }, {back}); }

  bonusScene(){const s=$("#screen"),prev=this.state,slides=["The last keepsake catches the morning light. Across the valley, every small memory answers: a shell, a seed, a stone, a path remembered.","The river carries their reflections together. Nothing was lost along the way. It was all part of the same long turning."];let i=0;this.state="bonus";$("#hud").hidden=true;$("#touch").hidden=true;s.hidden=false;s.className="screen ending";const show=()=>{if(i<slides.length){s.innerHTML='<div class="card"><p class="endtxt">'+esc(slides[i])+'</p><div class="menu row"><button class="btn primary" id="bonusNext">'+(i===slides.length-1?"Return to the trail":"Continue")+'</button></div></div>';$("#bonusNext").onclick=()=>{i++;if(i>=slides.length){s.hidden=true;this.state=prev;$("#hud").hidden=false;this.updateTouchVis();return;}show();};$("#bonusNext").focus();}};show();}
  // ---------------- ending & credits ----------------
  ending(){ const g=this.g, F=g.run.flags, h=g.h; const slides=[];
    slides.push("The weather clears the way weather does — not all at once, but enough. "+esc(h.name)+" stands at the edge of the coast where the storm first let go.");
    slides.push(F.gull_freed ? "A gull wheels overhead and lands on the leaning tree. It has been waiting, or it has simply decided this is a good tree." : "Gulls ride the wind above the inlet, busy with the morning.");
    slides.push(F.tovan_done ? "Tovan has planted weeds around the open shelter. They are thriving. He is insufferable about it." : "Tovan wanders the woods, talking to clover.");
    slides.push(F.kiln_lit ? "In Redleaf, Pella's kiln breathes steadily. Her new pots lean, as always, and sell faster than ever." : "Pella is still arguing with her kiln, and is beginning to win.");
    slides.push(F.kites_done ? "Nim's kites fly over Mirrorlake — one of them shaped vaguely like you, with very large wings." : "Nim is building a new kite. It will be the best one yet.");
    slides.push(F.beds_done ? "Underground, Seli's orchard grows pale apples by rootlight, three trees more than before." : "Underground, Seli tends the orchard, slowly.");
    const g_s = Object.keys(F).filter(k=>k.startsWith("g_")&&F[k]==="soothed").length; slides.push(g_s>=5 ? "The valley's great guardians rest easier. Most of them you never fought at all." : g_s>=1 ? "The guardians of the valley have settled — some soothed, some simply tired of standing their ground." : "The guardians you faced have withdrawn to rest. The valley is quieter for it, and none the less wild.");
    slides.push(F.aster_stay ? "Aster stays, as Aster chose. Visiting is a fine thing. Loving two places at once is finer." : F.aster_ask ? "Aster walks with you to the water, then stops. Some roads only go one way, for a while." : F.met_aster ? "The Traveler in the Blue Coat waves from the dunes, and then is simply part of the valley again." : "Somewhere in the dunes, someone in a blue coat watches you go, and smiles.");
    slides.push("There is a red boat at the waterline, sized for one small traveler. The way home is open. So is this place.");
    slides.push("The tide comes in. The tide goes out. The river turns, as rivers do. Nothing that changed is lost, only moved.");
    g.run.flags.ending_seen=1; let i=0; this.state="ending"; $("#hud").hidden=true; $("#touch").hidden=true; const s=$("#screen"); s.hidden=false; s.className="screen ending";
    const show=()=>{ if (i<slides.length) { s.innerHTML='<div class="card"><p class="endtxt">'+slides[i]+'</p><div class="menu row"><button class="btn primary" id="en">Continue</button></div></div>'; $("#en").onclick=()=>{ i++; A.sfx("menu"); show(); }; $("#en").focus(); }
      else { s.innerHTML='<div class="card"><h1 class="logo">Where the<br>River Turns</h1><p>Thank you for walking with us.</p><div class="menu"><button class="btn primary" id="ec">Continue Exploring</button><button class="btn" id="ecr">Credits</button><button class="btn" id="et">Return to Title</button></div></div>';
        $("#ec").onclick=()=>{ s.hidden=true; this.startPlay(); this.toast("The whole valley is open. Use the map to travel anywhere you have been.", true); };
        $("#ecr").onclick=()=>this.showCredits(()=>show()); $("#et").onclick=()=>{ this.g.run=null; this.showTitle(); }; this.focusFirst(s); } };
    A.sfx("done"); show(); }
  showCredits(back){ const s=$("#screen"); s.hidden=false; const prev=this.state; this.state="credits"; s.className="screen credits";
    s.innerHTML='<div class="card"><h2>Credits</h2><div class="credits">'+[["Story, dialogue & world","The River Turns team"],["Pixel art (procedural canvas)","The River Turns team"],["Music & sound (generated live)","The River Turns team"],["Level design — 162 levels","The River Turns team"],["Characters","Mira · Tovan · Wade · Eren · Hesk · Nim · Pella · Dov · Old Wenna · Yarrow · Tam · Oru · Seli · Aster · Brisk · Lowe · Pipkin"],["Creatures & guardians","Every one of them, for their patience"],["Playtesting","You"]].map(([a,b])=>'<div class="cr"><span>'+esc(a)+'</span><b>'+esc(b)+'</b></div>').join("")+'</div><button class="btn primary" id="cb">Back</button></div>';
    $("#cb").onclick=()=>{ this.state=prev; back(); }; $("#cb").focus(); }
}
